}

// 只改配乐时：重新合成 WAV，复制成片的视频流，换上新的 AAC 音轨。
function remuxAudio() {
  writeFileSync(WAV, toWav(synthesize()));
  const tmp = path.join(OUT_DIR, '换音轨.mp4');
  const mux = spawnSync('ffmpeg', ['-y', '-loglevel', 'error', '-i', TARGET, '-i', WAV, '-map', '0:v:0', '-map', '1:a:0', '-c:v', 'copy',
    '-c:a', 'aac', '-b:a', '256k', '-ar', '48000', '-map_metadata', '-1', '-movflags', '+faststart', '-t', String(SECONDS), tmp], {stdio: 'inherit'});
  if (mux.status !== 0) throw new Error(`换音轨失败 ${mux.status}`);
  renameSync(tmp, TARGET);
}

const args = process.argv.slice(2);
mkdirSync(OUT_DIR, {recursive: true});
if (args[0] === '--stills') await renderStills(args[1].split(',').map(Number), path.resolve(args[2]));
else if (args[0] === '--audio') remuxAudio();
else await renderAll();
export const FPS = 30;
export const BPM = 120;
export const BEAT_FRAMES = FPS * 60 / BPM;
export const BEATS = 180;
export const FRAME_COUNT = BEATS * BEAT_FRAMES;
export const SECONDS = FRAME_COUNT / FPS;
export const SAMPLE_RATE = 48000;

// 每页的拍数按阅读量安排。第 1—11 页暗场；上一页的元素在最后一两拍变成下一页的起点（墨点落地、纹理、
// 年份滚动、球升起、镜头拉远），每页在 land 那一帧发生一个明确的动作：大字落下、场景点亮或物件定格。
const LENGTHS = [
  ['open', 16],
  ['motto', 16],
  ['newark', 14],
  ['plan', 14],
  ['hire', 14],
  ['y1979', 14],
  ['aid', 12],
  ['exam', 12],
  ['creed', 16],
  ['notice', 12],
  ['drones', 12],
  ['ours', 14],
  ['end', 14],
];

export const PAGES = (() => {
  let beat = 0;
  return LENGTHS.map(([id, beats]) => {
    const page = {id, beats, beat, land: beat * BEAT_FRAMES, end: (beat + beats) * BEAT_FRAMES};
    beat += beats;
    return page;
  });
})();

// 开场：第 0 帧墨滴已在下落，第 1 拍落地炸开；第 3 拍起八个字每半拍在晶格地面上显影一个；
