export function extrema(s, n = 601) {
  const out = [];
  let prev = derivative(s, 1e-4), prevU = 1e-4;
  for (let i = 1; i <= n; i++) {
    const u = Math.min(1 - 1e-4, i / n);
    const d = derivative(s, u);
    // 恰好为零的采样不更新符号，变号区间跨过它继续找
    if (d === 0) continue;
    if (prev * d < 0) out.push(bisect(x => derivative(s, x), prevU, u));
    prev = d; prevU = u;
  }
  return out;
}

