}

function reverb(input) {
  const outBuf = new Float32Array(N);
  for (const [ms, fb] of [[31.3, 0.82], [37.1, 0.8], [41.9, 0.78], [47.3, 0.76]]) {
    const d = Math.round(ms * SR / 1000);
    const buf = new Float32Array(N);
    let lp = 0;
    for (let i = 0; i < N; i++) {
      const back = i >= d ? buf[i - d] : 0;
      lp = 0.6 * back + 0.4 * lp;
      buf[i] = input[i] + lp * fb;
