  sparkles(wet, panL, panR, at('cauchy', 8), at('cauchy', 56), 0.35, 52);
  for (const b of [KEYS.cauchy.formula, KEYS.cauchy.lagrange, KEYS.cauchy.title]) riser(dry, at('cauchy', b) - 2, at('cauchy', b), 0.14, 60 + b);
