    line(g, 300, 880, 300, 230, INK, 3, 'butt');
    textLine(g, 'g(t)', 1660, 940, MONO(40), INK, {align: 'right'});
    textLine(g, 'f(t)', 330, 250, MONO(40), INK);
    if (b >= K.chord) {
