    line(g, X, 866, X, 894, ORANGE, 8, 'butt');
    line(g, 286, Y, 314, Y, ORANGE, 8, 'butt');
    if (b >= K.chord) {
      const since = b - K.parallel;
      cauchyCurveTangent(g, t, 640 + (since >= 0 ? 500 * Math.max(0, 1 - since / 0.6) ** 2 : 0));
    }
    dot(g, X, Y, 17, ORANGE); dot(g, X, Y, 7, PAPER);
