// ---------- 场景五 胶片条与帧计数 ----------
const TW = 360, TH = 203, PITCH = 450, SLOT0 = 285, STRIP_Y = 470;
const CHAIN_FRAMES = [322, 1005, 1530, 2475];
const EXTRA_FRAMES = [40, 140, 240, 450, 700, 860, 1150, 1400, 1700, 1900, 2250, 2650, 2850];
