      slam(g, sprite(`code-arrow-${i}`, {t: TEXT.code.arrows[i], c: ORANGE}, 44), x, STRIP_Y - TH / 2 - 90, b, ab);
    });
    if (b >= K.root) {
      const q = outCubic(seg(b, K.root, K.root + 1));
      g.fillStyle = ORANGE;
      g.fillRect(SLOT0 - 60, STRIP_Y + 262, (3 * PITCH + 120) * q, 10);
      g.fillRect(SLOT0 - 60, STRIP_Y + 240, 10, 32);
      g.strokeStyle = ORANGE; g.lineWidth = 8; g.strokeRect(SLOT0 - TW / 2 - 4, STRIP_Y - TH / 2 - 4, TW + 8, TH + 8);
    }
    slam(g, sprite('code-root', TEXT.code.root, 88), 960, 900, b, K.rootText);
    return b < K.strip ? CALLS.code[0] : CALLS.code[1];
  }
  // 计数从 0 跑到 3600，接着“每一帧，都是代码画的”和逐字打出的代码
  const n = Math.round(3600 * outCubic(seg(b, K.counter, K.every)));
  g.font = TITLE(300);
  const full = g.measureText('3600 帧').width;
  const x0 = 960 - full / 2;
  const wDigits = textLine(g, String(n).padStart(4, '0'), x0, 470, TITLE(300), INK, {label: 'counter'});
  textLine(g, ' 帧', x0 + Math.max(wDigits, g.measureText('3600').width), 470, TITLE(300), INK, {label: 'counter unit'});
  if (b >= K.every) {
    const parts = [[TEXT.code.every + '，', INK, K.every], ['都是', INK, K.code], ['代码', ORANGE, K.code], ['画的', INK, K.code]];
    g.font = TITLE(130);
    const total = parts.reduce((s, [t]) => s + g.measureText(t).width, 0);
    let x = 960 - total / 2;
    for (const [t, c, b0] of parts) {
      const w = (g.font = TITLE(130), g.measureText(t).width);
      if (b >= b0) textLine(g, t, x, 690, TITLE(130), c);
      x += w;
    }
  }
  if (b >= K.code) {
    const typed = FINAL_CODE.slice(0, Math.ceil(FINAL_CODE.length * seg(b, K.code, K.code + 4)));
    g.font = MONO(46);
    const x = 960 - g.measureText(FINAL_CODE).width / 2;
    const w = textLine(g, typed, x, 860, MONO(46), INK, {label: 'final code'});
    if (Math.floor(b * 2) % 2 === 0 || typed.length < FINAL_CODE.length) { g.fillStyle = ORANGE; g.fillRect(x + w + 6, 822, 26, 48); }
  }
  if (b >= K.final) {
    const q = outExpo(seg(b, K.final, K.final + 0.4));
    g.fillStyle = ORANGE;
    g.fillRect(0, 742, W * q, 16);
  }
  return b < K.code ? CALLS.code[1] : CALLS.code[2];
}

// ---------- 渲染 ----------
const SCENE_FN = {fermat, rolle, lagrange, cauchy, code};

function drawFrame(g, frame) {
  FRAME = frame;
  const st = frameState(frame);
  paper(g);
  const call = SCENE_FN[st.scene.id](g, st.b);
  hud(g, frame, st.index, call);
}

function renderFrame(frame) {
  drawFrame(ctx, frame);
}

async function init() {
  const faces = [TITLE(100), MONO(40)];
  await Promise.all(faces.map(f => document.fonts.load(f, '费马罗尔拉格朗日柯西ξ′⇒−＝帧renderFrame')));
  for (const f of faces) if (!document.fonts.check(f, '费马ξ')) report(`字体未加载：${f}`);
  grain = canvas();
  {
    const g = grain.getContext('2d'), r = rng(5);
    for (let i = 0; i < 90000; i++) {
      g.fillStyle = r() < 0.5 ? 'rgba(22,20,18,0.06)' : 'rgba(255,255,255,0.18)';
      g.fillRect(Math.floor(r() * W), Math.floor(r() * H), 1 + (r() < 0.2), 1);
    }
  }
  fermatLayer = canvas();
  initParticles();
  thumbs = new Map();
  const full = canvas(), fg = full.getContext('2d');
  for (const f of [...EXTRA_FRAMES, ...CHAIN_FRAMES]) {
    drawFrame(fg, f);
    const t = canvas(TW, TH), tg = t.getContext('2d');
    tg.imageSmoothingQuality = 'high';
    tg.drawImage(full, 0, 0, TW, TH);
    thumbs.set(f, t);
