// 画面上的全部文字。中文与公式用标题字体，代码行用正文字体 Menlo。

export const TEXT = {
  fermat: {title: '费马引理', peak: '最高点，切线是平的', valley: '最低点，也是平的', law: '极值处，导数为零'},
  rolle: {title: '罗尔定理', sub: ['两端一样高', '怎么弯都行', '中间总有平切线'], why: '最高点在中间', fermat: '用费马引理'},
  lagrange: {planes: ['两端', '不一样高', '斜着看'], parallel: '切线和弦平行', shear: '罗尔，加一个倾斜', title: '拉格朗日中值定理', meaning: '弦的斜率＝某点切线斜率'},
  cauchy: {together: '两个函数，一起随 t 走', parallel: '还是：切线和弦平行', lagrange: '令 g(x)=x，就是拉格朗日', title: '柯西中值定理'},
  code: {names: ['费马', '罗尔', '拉格朗日', '柯西'], arrows: ['两端等高', '加一个倾斜', '换成参数'], root: '根源：极值处切线是平的', frames: '帧', every: '每一帧', drawn: '都是代码画的'},
};

// 左下角常驻的代码行：当前这一帧里画主体的那句调用。
export const CALLS = {
  fermat: ['slice(formula, 14)', 'plot(x => x**3/3 - x)', 'tangent(x0, x0*x0 - 1)', 'slice(formula, 14)'],
  rolle: ['morph(ring, line, t)', 'morph(shape[i], shape[i+1], t)', 'extrema(shape).map(flat)'],
  lagrange: ['camera.z += 600 * dt', 'y = f(x) + k*x', 'camera.lookAt(formula)', 'camera.dive(xi)'],
  cauchy: ['particles.burst(2600)', 'p = [g(t), f(t)]', 'particles.to(glyphs)'],
  code: ['strip.scroll(v)', 'for (n = 0; n < 3600; n++)', 'renderFrame(n)'],
};

// 结尾大字下方逐字打出的代码。
export const FINAL_CODE = 'for (let n = 0; n < 3600; n++) renderFrame(n);';

export function allText() {
  const out = [];
  const walk = v => (typeof v === 'string' ? out.push(v) : Object.values(v).forEach(walk));
  walk(TEXT);
  return out;
}

