// 结尾：胶片条急停的放映机声（间隔越来越大），计数时越来越快的滴答
{
  let t = at('code', 0) * BEAT, gap = 0.035;
  const stop = at('code', KEYS.code.strip) * BEAT - 0.06;
  while (t < stop) { addHat(dry, t, 0.16, 0.025); addTone(dry, t, 0.03, [[1800, 0.03]], 0.0005, 0.01); t += gap; gap *= 1.045; }
  const c0 = at('code', KEYS.code.counter) * BEAT, c1 = at('code', KEYS.code.every) * BEAT - 0.06;
  for (let k = 0; k < 40; k++) {
