224	
225	// ---------- 场景一 费马：大字切条拆开重组 ----------
226	const FX = x => 960 + x * 360, FY = y => 650 - y * 250;
227	const FM = x => -(250 / 360) * FERMAT.df(x);
228	let fermatLayer;
229	const fermatFormula = () => sprite('fermat-formula', ['f′(x', {t: '0', sub: true}, ') = ', {t: '0', c: ORANGE, id: 'zero'}], 250);
230	const FERMAT_POS = [960, 470];
231	
232	function fermatDotX(b) {
233	  const K = KEYS.fermat;
234	  if (b < K.peak) return lerp(FERMAT.x0, FERMAT.peak, inOut(seg(b, K.curveDone, K.peak)));
235	  if (b < 26) return FERMAT.peak;
236	  return lerp(FERMAT.peak, FERMAT.valley, inOut(seg(b, 26, K.valley)));
237	}
238	
239	function drawFermatGraph(g, b) {
240	  const K = KEYS.fermat;
241	  g.setTransform(1, 0, 0, 1, 0, 0);
242	  g.clearRect(0, 0, W, H);
243	  line(g, 120, 650, 1800, 650, INK, 3, 'butt');
244	  line(g, 960, 300, 960, 990, INK, 3, 'butt');
245	  g.fillStyle = INK;
246	  g.beginPath(); g.moveTo(1800, 650); g.lineTo(1776, 640); g.lineTo(1776, 660); g.fill();
247	  g.beginPath(); g.moveTo(960, 300); g.lineTo(950, 324); g.lineTo(970, 324); g.fill();
248	  const p = inOut(seg(b, K.formOut + 1, K.curveDone));
249	  if (p > 0) {
250	    const pts = [];
251	    const xEnd = lerp(FERMAT.x0, FERMAT.x1, p);
252	    for (let x = FERMAT.x0; x <= xEnd; x += 0.01) pts.push([FX(x), FY(FERMAT.f(x))]);
253	    pts.push([FX(xEnd), FY(FERMAT.f(xEnd))]);
254	    polyline(g, pts, INK, 7);
255	  }
256	  if (b >= K.curveDone) {
257	    const x = fermatDotX(b), X = FX(x), Y = FY(FERMAT.f(x));
258	    const since = Math.min(9, ...[b - K.peak, b - K.valley].filter(v => v >= 0));
259	    const len = 620 + 520 * Math.max(0, 1 - since / 0.6) ** 2;
260	    slopeSeg(g, X, Y, FM(x), len, ORANGE, 8);
261	    dot(g, X, Y, 15, ORANGE);
262	    dot(g, X, Y, 6, PAPER);
263	    const k = FERMAT.df(x);
264	    const below = x > 0.2;
265	    const tx = X + 34, ty = below ? Y + 92 : Y - 56;
266	    const w = textLine(g, 'k = ', tx, ty, MONO(42), INK, {label: 'slope'});
267	    textLine(g, fmt(k), tx + w, ty, MONO(42), ORANGE, {label: 'slope'});
268	  }
269	  const code = CALLS.fermat[1];
270	  const typed = code.slice(0, Math.floor(code.length * seg(b, K.formOut + 1, 12)));
271	  if (b >= K.formOut + 1 && b < K.peak) {
272	    const w = textLine(g, typed, 140, 200, MONO(56), INK, {label: 'plot code'});
273	    if (Math.floor(b * 2) % 2 === 0 || typed.length < code.length) { g.fillStyle = ORANGE; g.fillRect(140 + w + 6, 158, 30, 52); }
274	  }
275	}
276	
277	function fermat(g, b) {
278	  const K = KEYS.fermat;
279	  const form = fermatFormula();
280	  const title = sprite('fermat-title', TEXT.fermat.title, 120);
281	  const law = sprite('fermat-law', TEXT.fermat.law, 96);
282	  const peak = sprite('fermat-peak', TEXT.fermat.peak, 100);
283	  const valley = sprite('fermat-valley', TEXT.fermat.valley, 100);
284	  const [fx, fy] = FERMAT_POS;
285	  // 第 0 帧：一道橙色横线从左扫过画面
286	  if (b < 2) {
287	    const a = outExpo(seg(b, -0.12, 0.8)), z = inOut(seg(b, 0.9, 2));
288	    g.fillStyle = ORANGE;
289	    g.fillRect(W * z, fy - 9, W * (a - z), 18);
290	  }
291	  if (b < K.formOut + 1.5) {
292	    if (b < K.formOut) slit(g, form, fx, fy, b, 0, K.formIn, 'in', 3, {dist: 1100});
293	    else slit(g, form, fx, fy, b, K.formOut, K.formOut + 1, 'out', 4, {dist: 2200});
294	    if (b < K.formOut) slam(g, title, 960, 760, b, K.title);
295	    else slit(g, title, 960, 760, b, K.formOut, K.formOut + 0.8, 'out', 5, {n: 6, dist: 2200});
296	  }
