323	const RA = 360, RB = 1560, RY = 680, RAMP = 290;
324	const RX = u => lerp(RA, RB, u), RYf = v => RY - v * RAMP;
325	
326	function rolleShape(b) {
327	  const m = KEYS.rolle.morphs, S = ROLLE_SHAPES;
328	  for (let k = 0; k < m.length; k++) {
329	    if (b < m[k] - 1) return {fn: S[k], land: k ? m[k - 1] : -9};
330	    if (b < m[k]) {
331	      const e = outBack(seg(b, m[k] - 1, m[k]));
332	      return {fn: u => lerp(S[k](u), S[k + 1](u), e), land: k ? m[k - 1] : -9, moving: true};
333	    }
334	  }
335	  return {fn: S[m.length], land: m[m.length - 1]};
336	}
337	
338	const mixColor = (a, b, t) => {
339	  const pa = [1, 3, 5].map(i => parseInt(a.slice(i, i + 2), 16)), pb = [1, 3, 5].map(i => parseInt(b.slice(i, i + 2), 16));
340	  return `rgb(${pa.map((v, i) => Math.round(lerp(v, pb[i], t))).join(',')})`;
341	};
342	
343	function rolle(g, b) {
344	  const K = KEYS.rolle;
345	  const form = fermatFormula();
346	  const zero = spriteRect(form, 'zero', ...FERMAT_POS);
347	  // 0—3 拍：“0”的圆环压扁成两端等高的直线
348	  const e = inOut(seg(b, 0, K.ring));
349	  const {fn, land, moving} = rolleShape(b);
350	  const M = 240, pts = [];
351	  const cx = (zero.x0 + zero.x1) / 2, cy = (zero.y0 + zero.y1) / 2, rx = (zero.x1 - zero.x0) / 2 - 12, ry = (zero.y1 - zero.y0) / 2 - 12;
352	  if (e < 1) {
353	    for (let j = 0; j <= M; j++) {
354	      const th = Math.PI - 2 * Math.PI * j / M;
355	      const u = j <= M / 2 ? 2 * j / M : 2 - 2 * j / M;
356	      pts.push([lerp(cx + rx * Math.cos(th), RX(u), e), lerp(cy - ry * Math.sin(th), RYf(0), e)]);
357	    }
358	    polyline(g, pts, mixColor(ORANGE, INK, e), lerp(24, 7, e));
359	  } else {
360	    for (let j = 0; j <= M; j++) pts.push([RX(j / M), RYf(fn(j / M))]);
361	  }
362	  // 两端的钉子和等高虚线
363	  if (b >= K.ring - 0.6) {
364	    const q = seg(b, K.ring - 0.6, K.ring);
365	    const y = lerp(-60, RY, q * q);
366	    if (b >= K.ring) dashed(g, RA, RY, RB, RY, INK, 3, -b * 12);
367	    if (e >= 1) polyline(g, pts, INK, 7);
368	    for (const x of [RA, RB]) { dot(g, x, y, 17, ORANGE); dot(g, x, y, 7, PAPER); }
369	    if (b >= K.ring) {
370	      textLine(g, 'f(a)', RA - 36, RY + 14, MONO(40), INK, {align: 'right'});
371	      textLine(g, 'f(b)', RB + 36, RY + 14, MONO(40), INK);
372	    }
373	  }
374	  // 平切线：对当前（包括正在变形的）曲线实时求极值
375	  if (b >= K.morphs[0] - 1) {
376	    const pop = Math.max(0, 1 - (b - land) / 0.35);
377	    for (const u of extrema(fn, 301)) {
378	      const X = RX(u), Y = RYf(fn(u));
379	      line(g, X - 110 * (1 + 0.5 * pop), Y, X + 110 * (1 + 0.5 * pop), Y, ORANGE, 8);
380	      dot(g, X, Y, 9, INK);
381	    }
382	  }
383	  if (b >= K.why) {
384	    const u = 0.5, X = RX(u), Y = RYf(fn(u));
385	    dashed(g, X, Y + 20, X, RY - 6, INK, 3);
386	    dot(g, X, Y, 20, ORANGE);
387	    dot(g, X, Y, 8, PAPER);
388	    slam(g, sprite('rolle-xi', {t: 'ξ', c: ORANGE}, 72), X, RY + 64, b, K.why + 0.5);
389	  }
390	  slam(g, sprite('rolle-title', TEXT.rolle.title, 120), 140, 170, b, K.title, {left: true});
391	  const subs = [[K.sub[0], TEXT.rolle.sub[0]], [K.sub[1], TEXT.rolle.sub[1]], [K.sub[2], TEXT.rolle.sub[2]], [K.why, TEXT.rolle.why], [K.fermat, TEXT.rolle.fermat]];
392	  const cur = subs.findLast(([s]) => b >= s);
393	  if (cur) slam(g, sprite(`rolle-sub-${cur[1]}`, cur[1], 76), 140, 300, b, cur[0], {left: true});
394	  if (b >= K.formula[0]) {
395	    const parts = [sprite('rolle-f1', 'f(a) = f(b)', 96), sprite('rolle-f2', '⇒', 96), sprite('rolle-f3', ['f′(', {t: 'ξ', c: ORANGE}, ') = 0'], 96)];
396	    const widths = parts.map(p => p.ink.x1 - p.ink.x0), gap = 60;
397	    let x = 960 - (widths.reduce((a, c) => a + c, 0) + gap * 2) / 2;
398	    parts.forEach((p, i) => { slam(g, p, x, 935, b, K.formula[i], {left: true}); x += widths[i] + gap; });
399	  }
400	  return b < 8 ? CALLS.rolle[0] : b < K.why ? CALLS.rolle[1] : CALLS.rolle[2];
401	}
