532	function samplePoints(sp, cx, cy, seed) {
533	  const data = sp.c.getContext('2d', {willReadFrequently: true}).getImageData(0, 0, sp.w, sp.h).data;
534	  const pts = [];
535	  for (let y = 0; y < sp.h; y += 3) for (let x = 0; x < sp.w; x += 3) {
536	    const i = (y * sp.w + x) * 4;
537	    if (data[i + 3] > 150) pts.push([cx - sp.w / 2 + x, cy - sp.h / 2 + y, data[i] > 200 && data[i + 1] < 160 ? 1 : 0]);
538	  }
539	  const order = perm(seed, pts.length);
540	  const xy = new Float32Array(NP * 2), col = new Uint8Array(NP);
541	  for (let i = 0; i < NP; i++) { const p = pts[order[i % pts.length]]; xy[2 * i] = p[0]; xy[2 * i + 1] = p[1]; col[i] = p[2]; }
542	  return {xy, col};
543	}
