545	const cauchyForm1 = () => sprite('cau-f1', [{frac: [['f′(ξ)'], [{t: 'g′(ξ)', c: ORANGE}]]}, ' = ', {frac: [['f(b) − f(a)'], [{t: 'g(b) − g(a)', c: ORANGE}]]}], 118);
546	const cauchyForm2 = () => sprite('cau-f2', ['f′(ξ) = ', {frac: [['f(b) − f(a)'], [{t: 'b − a', c: ORANGE}]]}], 118);
547	const cauchyTitle = () => sprite('cau-title', TEXT.cauchy.title, 170);
548	
549	function initParticles() {
550	  const r = rng(77);
551	  P.delay = new Float32Array(NP); P.arc = new Float32Array(NP); P.phase = new Float32Array(NP); P.t = new Float32Array(NP);
552	  P.burst = {xy: new Float32Array(NP * 2), col: new Uint8Array(NP).fill(1)};
553	  P.curve = {xy: new Float32Array(NP * 2), col: new Uint8Array(NP)};
554	  for (let i = 0; i < NP; i++) {
555	    P.delay[i] = r(); P.arc[i] = (r() * 2 - 1) * 220; P.phase[i] = r() * Math.PI * 2;
556	    const a = r() * Math.PI * 2, rad = 140 + 820 * r() ** 0.8;
557	    P.burst.xy[2 * i] = 960 + Math.cos(a) * rad * 1.3; P.burst.xy[2 * i + 1] = 540 + Math.sin(a) * rad * 0.75;
558	    const t = (i + r()) / NP;
559	    P.t[i] = t;
560	    const dx = CAUCHY.dg(t) * 1160, dy = -CAUCHY.df(t) * 650, n = Math.hypot(dx, dy), j = (r() * 2 - 1) * 7;
561	    P.curve.xy[2 * i] = CX(t) - dy / n * j; P.curve.xy[2 * i + 1] = CY(t) + dx / n * j;
562	  }
563	  P.form1 = samplePoints(cauchyForm1(), 960, 480, 91);
564	  P.form2 = samplePoints(cauchyForm2(), 960, 480, 92);
565	  P.title = samplePoints(cauchyTitle(), 960, 500, 93);
566	}
567	
568	// 从布局 A 飞到布局 B：每个粒子有自己的延迟和弧线，q 为整段进度
569	function flight(A, B, q, spread, delayOf, out) {
570	  for (let i = 0; i < NP; i++) {
571	    const d = delayOf ? delayOf(i) : P.delay[i];
572	    const qi = clamp((q - d * spread) / (1 - spread));
573	    const e = inOut(qi);
574	    const ax = A.xy[2 * i], ay = A.xy[2 * i + 1], bx = B.xy[2 * i], by = B.xy[2 * i + 1];
575	    const dx = bx - ax, dy = by - ay, n = Math.hypot(dx, dy) || 1, bump = P.arc[i] * Math.sin(Math.PI * e);
576	    out.xy[2 * i] = lerp(ax, bx, e) - dy / n * bump;
577	    out.xy[2 * i + 1] = lerp(ay, by, e) + dx / n * bump;
578	    out.col[i] = e < 0.5 ? A.col[i] : B.col[i];
579	  }
580	}
581	
582	function drawParticles(g, L, size, b) {
583	  for (const [c, flag] of [[INK, 0], [ORANGE, 1]]) {
584	    g.fillStyle = c;
585	    for (let i = 0; i < NP; i++) {
586	      if (L.col[i] !== flag) continue;
587	      const x = L.xy[2 * i] + 2.5 * Math.sin(b * 2.1 + P.phase[i]), y = L.xy[2 * i + 1] + 2.5 * Math.cos(b * 1.7 + P.phase[i]);
588	      g.fillRect(x - size / 2, y - size / 2, size, size);
589	    }
590	  }
591	}
592	
593	function cauchyCurveTangent(g, t, len) {
594	  const m = -(CAUCHY.df(t) * 650) / (CAUCHY.dg(t) * 1160);
595	  slopeSeg(g, CX(t), CY(t), m, len, ORANGE, 7);
596	}
