598	function cauchy(g, b) {
599	  const K = KEYS.cauchy;
600	  const L = {xy: new Float32Array(NP * 2), col: new Uint8Array(NP)};
601	  const center = {xy: new Float32Array(NP * 2).map((_, i) => (i % 2 ? 540 : 960)), col: P.burst.col};
602	  let solid = null, size = 4;
603	  if (b < 3) { flight(center, P.burst, outExpo(seg(b, 0, 2.5)), 0, () => 0, L); size = 6; }
604	  else if (b < K.curve) flight(P.burst, P.curve, seg(b, 3, K.curve), 0.58, i => P.t[i], L);
605	  else if (b < 24) flight(P.curve, P.curve, 1, 0, null, L);
606	  else if (b < K.formula) flight(P.curve, P.form1, seg(b, 24, K.formula - 0.3), 0.4, null, L);
607	  else if (b < 36) solid = [cauchyForm1(), 960, 480];
608	  else if (b < K.lagrange) flight(P.form1, P.form2, seg(b, 36, K.lagrange - 0.3), 0.35, null, L);
609	  else if (b < 44) solid = [cauchyForm2(), 960, 480];
610	  else if (b < K.title) flight(P.form2, P.title, seg(b, 44, K.title - 0.3), 0.4, null, L);
611	  else if (b < 53) solid = [cauchyTitle(), 960, 500];
612	  else {
613	    for (let i = 0; i < NP; i++) {
614	      const q = Math.max(0, b - 53 - P.delay[i] * 2.2);
615	      L.xy[2 * i] = P.title.xy[2 * i] + 820 * q * q + 60 * q;
616	      L.xy[2 * i + 1] = P.title.xy[2 * i + 1];
617	      L.col[i] = P.title.col[i];
618	    }
619	  }
620	  // 两个函数一起随 t 走：轴、t 点在两轴上的投影、弦与切线
621	  if (b >= K.together && b < 24) {
622	    line(g, 300, 880, 1660, 880, INK, 3, 'butt');
623	    line(g, 300, 880, 300, 230, INK, 3, 'butt');
624	    textLine(g, 'g(t)', 1660, 940, MONO(40), INK, {align: 'right'});
625	    textLine(g, 'f(t)', 330, 250, MONO(40), INK);
626	    if (b >= K.chord) {
627	      const q = outCubic(seg(b, K.chord, K.chord + 1));
628	      line(g, CX(0), CY(0), lerp(CX(0), CX(1), q), lerp(CY(0), CY(1), q), ORANGE, 6);
629	    }
630	    const t = b < K.chord ? inOut(seg(b, K.curve, 15)) : lerp(0.06, CAUCHY.xi, inOut(seg(b, K.chord, K.parallel)));
631	    const X = CX(t), Y = CY(t);
632	    dashed(g, X, Y, X, 880, INK, 3);
633	    dashed(g, X, Y, 300, Y, INK, 3);
634	    line(g, X, 866, X, 894, ORANGE, 8, 'butt');
635	    line(g, 286, Y, 314, Y, ORANGE, 8, 'butt');
636	    if (b >= K.chord) {
637	      const since = b - K.parallel;
638	      cauchyCurveTangent(g, t, 640 + (since >= 0 ? 500 * Math.max(0, 1 - since / 0.6) ** 2 : 0));
639	    }
640	    dot(g, X, Y, 17, ORANGE); dot(g, X, Y, 7, PAPER);
641	    textLine(g, `t = ${t.toFixed(2)}`, 1660, 250, MONO(44), INK, {align: 'right'});
642	  }
643	  if (solid) drawSprite(g, ...solid);
644	  else drawParticles(g, L, size, b);
645	  if (b >= K.together && b < K.parallel) slam(g, sprite('cau-together', TEXT.cauchy.together, 84), 140, 150, b, K.together, {left: true});
