import {spawnSync} from 'node:child_process';
import {writeFileSync} from 'node:fs';
import {HIT_BEATS} from '../../../微分中值定理/短片/timeline.js';
import {synthesize, toWav} from '../../../微分中值定理/短片/music.mjs';
import {TARGET} from '../../../微分中值定理/短片/render.mjs';

const SR = 48000;
const {left, right} = synthesize();
const mono = left.map((v, i) => (v + right[i]) / 2);
const steps = [];
for (let i = 1; i < left.length; i++) {
  const s = Math.max(Math.abs(left[i] - left[i - 1]), Math.abs(right[i] - right[i - 1]));
  if (s > 0.3) steps.push([Number((i / SR).toFixed(4)), Number(s.toFixed(3))]);
}
console.log('steps>0.3', steps.length, steps.slice(0, 12));
const win = SR / 100;
const energy = s0 => { let e = 0; for (let i = Math.max(0, s0); i < s0 + win; i++) e += mono[i] ** 2; return e; };
const off = [];
for (const beat of HIT_BEATS) {
  const center = Math.round(beat * 0.5 * SR);
  let best = center, bestRise = -Infinity;
  for (let s = center - SR * 0.03; s <= center + SR * 0.03; s += SR / 1000) {
    const rise = energy(s) - energy(s - win);
    if (rise > bestRise) { bestRise = rise; best = s; }
  }
  const ms = Math.round((best - center) / SR * 1000);
  if (Math.abs(ms) > 3) off.push([beat, ms]);
}
console.log('accent offsets >3ms', off);
