  const PX = 480 * 270, d = [];
  for (let f = 1; f < raw.length / PX; f++) { let s = 0; for (let i = 0; i < PX; i++) s += Math.abs(raw[f * PX + i] - raw[(f - 1) * PX + i]); d.push([2152 + f, Number((s / PX).toFixed(1))]); }
  console.log('diffs', d);
}

