// 用导出检查同一种起音偏差算法（±30 ms 内 10 ms 能量窗上升最大处）测：
// ① 原始 bgm.mp3 相对它自己拟合的拍格；② 剪辑后的 bgm 单轨相对成片拍格。两者相近说明偏差来自 bgm 的鼓声形状，不是拉伸错位。
import {spawnSync} from 'node:child_process';
import {readFileSync} from 'node:fs';

const SR = 48000;
const decode = file => {
  const r = spawnSync('ffmpeg', ['-v', 'error', '-i', file, '-ar', String(SR), '-ac', '1', '-f', 'f32le', '-'], {maxBuffer: 2 ** 31});
  return new Float32Array(r.stdout.buffer, r.stdout.byteOffset, r.stdout.length / 4);
};
const win = SR / 100;
function offsets(x, times) {
  const energy = s0 => { let e = 0; for (let i = Math.max(0, s0); i < s0 + win; i++) e += x[i] ** 2; return e; };
  return times.map(t => {
    const c = Math.round(t * SR);
    let best = c, bestRise = -Infinity;
    for (let s = c - SR * 0.03; s <= c + SR * 0.03; s += SR / 1000) {
      const rise = energy(s) - energy(s - win);
      if (rise > bestRise) { bestRise = rise; best = s; }
    }
    return Math.round((best - c) / SR * 1000);
  });
}
const stats = a => { const s = [...a].sort((p, q) => p - q); return {median: s[Math.floor(s.length / 2)], p10: s[Math.floor(s.length * 0.1)], p90: s[Math.floor(s.length * 0.9)]}; };
const A = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const orig = decode(process.argv[3]);
const tOrig = Array.from({length: 280}, (_, k) => A.firstBeat + k * A.period).filter(t => t > 0.1);
console.log('原始 bgm 相对自身拍格', stats(offsets(orig, tOrig)));
const stem = decode(process.argv[4]);
const tStem = Array.from({length: 268}, (_, k) => 0.5 * k).filter(t => t > 0.1);
console.log('剪辑后单轨相对成片拍格', stats(offsets(stem, tStem)));

