266	export function synthesize() {
267	  const dry = new Float32Array(N), wet = new Float32Array(N);
268	  const panL = new Float32Array(N), panR = new Float32Array(N);
269	
270	  for (let beat = 0; beat < BEATS; beat++) {
271	    const t = beat * BEAT;
272	    const scene = sceneAt(beat);
273	    const arr = ARR[scene.id](beat - scene.beat);
274	    const bar = beat % 4;
275	    if (beat >= FINAL_BEAT) continue;
276	    const pc = rootAt(beat), r = pitch(pc, 53);
277	    if (arr.drone && bar === 0) addTone(dry, t, BEAT * 4 + 0.1, [[midi(pitch(pc, 29)), 0.09 * arr.drone], [midi(pitch(pc, 29) + 7), 0.025 * arr.drone]], 0.2, 3);
278	    if (arr.pluck) {
279	      const notes = [r, r + 7, r + 12, r + 19, r + 12, r + 7, r + 12, r + 24];
280	      const steps = arr.sixteenth ? 4 : 2;
281	      for (let k = 0; k < steps; k++) {
282	        const target = k % 2 ? panR : panL;
283	        const g = (arr.sixteenth ? 0.075 : 0.1) * arr.pluck * (k === 0 ? 1.2 : 1);
284	        const note = notes[(bar * steps + k) % notes.length];
285	        addPluck(target, t + k * BEAT / steps, midi(note), g);
286	        addPluck(wet, t + k * BEAT / steps, midi(note), g * 0.3);
287	      }
288	    }
289	    if (arr.keys && bar % 2 === 0) {
290	      const m = bar === 0 ? r + 12 : r + 7;
291	      addTone(dry, t, 2, [[midi(m), 0.045 * arr.keys], [midi(m) * 2, 0.01 * arr.keys], [midi(m) * 3, 0.004 * arr.keys]], 0.004, 0.7);
292	      addTone(wet, t, 2, [[midi(m), 0.03 * arr.keys]], 0.004, 0.7);
293	    }
294	  }
295	
296	  overture(dry, wet);
297	
298	  // 费马：切条飞入的两声风声，公式锁定前停住
299	  addSweep(dry, at('fermat', 0) * BEAT, 2 * BEAT - 0.05, 0.22, 3000, 700, x => (1 - x) ** 1.5, 11);
300	  addSweep(dry, at('fermat', KEYS.fermat.formOut) * BEAT, BEAT, 0.16, 800, 4000, x => Math.sin(Math.PI * x), 12);
301	  addSweep(dry, (at('fermat', KEYS.fermat.formBack) - 1) * BEAT, BEAT - 0.05, 0.18, 600, 5000, x => x ** 2, 13);
302	  riser(dry, at('rolle', 0) - 2, at('rolle', 0), 0.2, 14);
303	
304	  // 罗尔：每次变形前一拍的风声推到落定
305	  for (const [i, b] of KEYS.rolle.morphs.entries()) addSweep(dry, (at('rolle', b) - 1) * BEAT, BEAT - 0.05, 0.13, 500, 3500, x => x ** 1.6, 30 + i);
306	  riser(dry, at('lagrange', 0) - 4, at('lagrange', 0), 0.22, 15);
307	
308	  // 拉格朗日：穿过每块文字平面时的风声；斜率摆动时的钟声；对齐前的上扬；俯冲进 ξ 的上扬
309	  for (const [i, b] of KEYS.lagrange.passes.entries()) {
310	    const t = at('lagrange', b) * BEAT;
311	    addSweep(dry, t - 0.45, 0.9, 0.22, 600, 6000, x => Math.sin(Math.PI * x) ** 2, 40 + i);
312	  }
313	  for (const [i, b] of KEYS.lagrange.swings.entries()) {
314	    const t = at('lagrange', b) * BEAT;
315	    const m = [84, 87, 89][i];
316	    addTone(wet, t, 1, [[midi(m), 0.05], [midi(m) * 2.76, 0.012]], 0.002, 0.3);
317	  }
318	  riser(dry, at('lagrange', KEYS.lagrange.align) - 8, at('lagrange', KEYS.lagrange.align), 0.24, 16);
319	  riser(dry, at('lagrange', KEYS.lagrange.dive) - 6, at('lagrange', KEYS.lagrange.dive), 0.3, 17);
320	
321	  // 柯西：粒子的高音碎点（F 小调五声音阶）
322	  sparkles(wet, panL, panR, at('cauchy', 0), at('cauchy', 8), 0.9, 51);
323	  sparkles(wet, panL, panR, at('cauchy', 8), at('cauchy', 56), 0.35, 52);
324	  for (const b of [KEYS.cauchy.formula, KEYS.cauchy.lagrange, KEYS.cauchy.title]) riser(dry, at('cauchy', b) - 2, at('cauchy', b), 0.14, 60 + b);
325	  riser(dry, at('chain', 0) - 4, at('chain', 0), 0.24, 18);
326	
327	  // 结尾：胶片条急停的放映机声（间隔越来越大）；回到费马公式和最后一道横线前各一段上扬
328	  {
329	    let t = at('chain', 0) * BEAT, gap = 0.035;
330	    const stop = at('chain', KEYS.chain.strip) * BEAT - 0.06;
331	    while (t < stop) { addHat(dry, t, 0.11, 0.025); addTone(dry, t, 0.03, [[1800, 0.03]], 0.0005, 0.01); t += gap; gap *= 1.045; }
332	    riser(dry, at('chain', KEYS.chain.formula) - 2, at('chain', KEYS.chain.formula), 0.18, 19);
333	    riser(dry, at('chain', KEYS.chain.final) - 2, at('chain', KEYS.chain.final), 0.2, 20);
334	  }
335	
336	  const bigBeats = new Set([...SCENES.map(s => s.beat), FINAL_BEAT, at('chain', KEYS.chain.formula), at('overture', KEYS.overture.title)]);
337	  for (const [i, beat] of HIT_BEATS.entries()) impact(dry, wet, beat, bigBeats.has(beat) ? 1 : 0.6, 200 + i);
338	
339	  // 结尾和弦：F 小调主和弦
340	  {
341	    const t = FINAL_BEAT * BEAT;
342	    for (const m of [53, 56, 60, 65]) addTone(wet, t, SECONDS - t, [[midi(m), 0.03], [midi(m) * 1.004, 0.02], [midi(m + 12), 0.008]], 0.01, 3.5);
343	    addTone(dry, t, SECONDS - t, [[midi(29), 0.14], [midi(41), 0.04]], 0.01, 2.5);
344	  }
345	
346	  const verb = reverb(wet);
347	  const bgm = loadBgm();
348	  // bgm 在开场压低，让大鼓和低音重击在前；28 拍起随上扬回升，费马切点回到原音量
349	  const ov = at('overture', KEYS.overture.dive) * BEAT, full = at('fermat', 0) * BEAT;
350	  // 其余每个切点前 150 ms 也把 bgm 压下去，让切点重击和 bgm 自己的鼓拉开
351	  const cuts = SCENES.slice(2).map(s => s.beat * BEAT);
352	  const bgmGain = t => {
353	    if (t < ov) return 0.5;
354	    if (t < full - 0.2) return 0.5 + 0.5 * ((t - ov) / (full - ov)) ** 2;
355	    if (t < full) return 0.12;
356	    return cuts.some(c => t >= c - 0.15 && t < c) ? 0.3 : 1;
357	  };
358	  const SYN = 0.75, BG = 1.6;
359	  const left = new Float32Array(N), right = new Float32Array(N);
360	  let peak = 0;
361	  for (let i = 0; i < N; i++) {
362	    const fade = Math.min(1, (N - i) / (SR * 1.5), i / (SR * 0.004));
363	    const gb = BG * bgmGain(i / SR);
364	    left[i] = (SYN * (dry[i] + panL[i] + 0.45 * panR[i] + verb[i]) + gb * bgm.left[i]) * fade;
365	    right[i] = (SYN * (dry[i] + panR[i] + 0.45 * panL[i] + verb[i] * 0.94) + gb * bgm.right[i]) * fade;
366	    peak = Math.max(peak, Math.abs(left[i]), Math.abs(right[i]));
367	  }
368	  // 软限幅压住重击的瞬时峰值，bgm 所在的中低电平基本线性；AAC 编码后真峰值会比 WAV 高约 1 dB，输出峰值留在约 -2.5 dBFS。
369	  const drive = 2.3, norm = 0.75 / Math.tanh(drive);
370	  for (let i = 0; i < N; i++) {
371	    left[i] = Math.tanh(drive * left[i] / peak) * norm;
372	    right[i] = Math.tanh(drive * right[i] / peak) * norm;
