  }
  addSweep(out, t0, 0.25, gain * 0.55, 900, 200, x => Math.exp(-x * 6) * Math.min(1, x * 300), seed);
  addSweep(out, t0, 0.012, gain * 0.9, 5000, 2500, x => (1 - x) * Math.min(1, x * 40), seed + 1);
}

